<?php
require_once __DIR__ . '/includes/functions.php';
$slug = trim((string) ($_GET['slug'] ?? ''));
$stmt = db()->prepare('SELECT p.*,c.name AS category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.slug=? AND p.is_active=1 LIMIT 1');
$stmt->execute([$slug]);
$product = $stmt->fetch();
if (!$product) { http_response_code(404); $pageTitle = 'Fabric not found | Yucca Fabrics'; require __DIR__ . '/includes/header.php'; echo '<section class="mx-auto max-w-3xl px-5 py-24 text-center"><h1 class="font-serif text-4xl">We couldn’t find that fabric</h1><a class="mt-6 inline-block underline" href="' . e(url('shop.php')) . '">Back to the collection</a></section>'; require __DIR__ . '/includes/footer.php'; exit; }
$photos = db()->prepare('SELECT image,alt_text FROM product_images WHERE product_id=? ORDER BY sort_order,id');
$photos->execute([$product['id']]);
$images = $photos->fetchAll();
$price = $product['sale_price'] !== null ? (float) $product['sale_price'] : (float) $product['price'];
$relatedStmt = db()->prepare('SELECT p.*, c.name AS category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.category_id=? AND p.id<>? AND p.is_active=1 LIMIT 4');
$relatedStmt->execute([$product['category_id'], $product['id']]);
$related = $relatedStmt->fetchAll();
$reviewStmt=db()->prepare("SELECT pr.rating,pr.title,pr.review,pr.created_at,u.name FROM product_reviews pr JOIN users u ON u.id=pr.user_id WHERE pr.product_id=? AND pr.status='approved' ORDER BY pr.created_at DESC LIMIT 10");
$reviewStmt->execute([$product['id']]);$reviews=$reviewStmt->fetchAll();
$canReview=false;
if(current_user()&&current_user()['role']==='customer'){$eligible=db()->prepare("SELECT o.id FROM orders o JOIN order_items oi ON oi.order_id=o.id WHERE o.user_id=? AND oi.product_id=? AND o.status='delivered' LIMIT 1");$eligible->execute([current_user()['id'],$product['id']]);$canReview=(bool)$eligible->fetchColumn();}
$pageTitle = $product['name'] . ' | Yucca Fabrics';
$schemaImage=$product['image']?absolute_url('uploads/products/'.rawurlencode(basename($product['image']))):absolute_url(PRODUCT_PLACEHOLDER_IMAGE);
$structuredData=['@context'=>'https://schema.org','@type'=>'Product','name'=>$product['name'],'description'=>$product['description'],'sku'=>$product['sku'],'image'=>$schemaImage,'offers'=>['@type'=>'Offer','priceCurrency'=>CURRENCY,'price'=>(string)$price,'availability'=>(int)$product['stock']>0?'https://schema.org/InStock':'https://schema.org/OutOfStock','url'=>absolute_url('product-details.php?slug='.rawurlencode($product['slug']))]];
require __DIR__ . '/includes/header.php';
?>
