<section class="mt-7 grid gap-10 md:grid-cols-2"><div><img id="product-image" class="aspect-[4/5] w-full rounded-3xl bg-white object-cover shadow-lg" src="<?= e(product_image($product['image'])) ?>" alt="<?= e($product['name']) ?>"><?php if ($images): ?><div class="mt-3 flex gap-3"><?php foreach ($images as $image): ?><button type="button" class="h-20 w-20 overflow-hidden rounded-xl border border-ink/10 transition hover:border-forest" data-image="<?= e(url('uploads/products/' . rawurlencode(basename($image['image'])))) ?>"><img src="<?= e(url('uploads/products/' . rawurlencode(basename($image['image'])))) ?>" alt="<?= e($image['alt_text'] ?: $product['name']) ?>" class="h-full w-full object-cover"></button><?php endforeach; ?></div><?php endif; ?></div>
<div class="py-3 md:py-10"><p class="eyebrow"><?= e($product['category_name'] ?? 'Yucca collection') ?></p><h1 class="mt-3 font-serif text-4xl sm:text-5xl"><?= e($product['name']) ?></h1><p class="mt-4 text-2xl font-semibold text-forest"><?= product_price_html($product) ?></p><p class="mt-2 text-xs text-gray-500">SKU <?= e($product['sku']) ?></p><p class="mt-5 text-sm leading-7 text-gray-600"><?= nl2br(e($product['description'])) ?></p><div class="mt-6 grid grid-cols-2 gap-y-3 border-y border-black/10 py-5 text-sm"><span class="text-gray-500">Colour</span><span><?= e($product['colour'] ?: 'Ask us') ?></span><span class="text-gray-500">Material</span><span><?= e($product['material'] ?: 'See description') ?></span><span class="text-gray-500">Availability</span><span><?= (int) $product['stock'] > 0 ? 'In stock · ' . (int) $product['stock'] . ' ' . e($product['unit']) . ((int) $product['stock'] === 1 ? '' : 's') : 'Currently unavailable' ?></span></div>
<?php if ((int) $product['stock'] > 0): ?><div class="mt-7 flex flex-wrap items-center gap-3"><label class="text-sm" for="quantity">Quantity (<?= e($product['unit']) ?>)</label><input id="quantity" name="quantity" type="number" min="1" max="<?= (int) $product['stock'] ?>" value="1" class="form-control w-24"><button data-add-cart="<?= (int) $product['id'] ?>" class="rounded-full bg-forest px-7 py-3 text-sm font-semibold text-white">Add to bag</button></div><?php endif; ?><ul class="mt-8 grid gap-3 rounded-3xl bg-white p-5 text-sm shadow-sm ring-1 ring-ink/5">
    <li class="flex gap-3"><i class="fa-solid fa-truck-fast mt-0.5 w-5 text-center text-sage" aria-hidden="true"></i><span><strong>Delivery <?= e(money(DELIVERY_FEE)) ?></strong><span class="block text-xs text-gray-600">Confirmed with you after you order.</span></span></li>
    <li class="flex gap-3"><i class="fa-solid fa-mobile-screen-button mt-0.5 w-5 text-center text-sage" aria-hidden="true"></i><span><strong>Pay your way</strong><span class="block text-xs text-gray-600">M-Pesa, bank transfer or cash on delivery.</span></span></li>
    <li class="flex gap-3"><i class="fa-solid fa-couch mt-0.5 w-5 text-center text-sage" aria-hidden="true"></i><span><strong>Want it upholstered?</strong><span class="block text-xs text-gray-600"><a class="font-semibold text-forest underline" href="<?= e(url('services.php#request-form')) ?>">Request a quote</a> and we’ll do the work for you.</span></span></li>
    <li class="flex gap-3"><i class="fa-solid fa-swatchbook mt-0.5 w-5 text-center text-sage" aria-hidden="true"></i><span><strong>Not sure yet?</strong><span class="block text-xs text-gray-600"><a class="font-semibold text-forest underline" href="<?= e(url('consultations.php?type=' . rawurlencode('Fabric and colour selection') . '#book')) ?>">Book a fabric consultation</a> to compare samples.</span></span></li>
</ul></div></section>
<section class="mt-12 border-t border-ink/10 py-12"><h2 class="font-serif text-3xl">Customer reviews</h2><?php if($reviews): ?><div class="mt-6 grid gap-4 md:grid-cols-2"><?php foreach($reviews as $review): ?><article class="rounded-3xl bg-white p-6 shadow-sm ring-1 ring-ink/5"><p class="text-clay"><?= str_repeat('★',(int)$review['rating']) ?><span class="text-gray-300"><?= str_repeat('★',5-(int)$review['rating']) ?></span></p><?php if($review['title']): ?><h3 class="mt-2 font-semibold"><?= e($review['title']) ?></h3><?php endif; ?><p class="mt-2 text-sm leading-6 text-gray-600"><?= e($review['review']) ?></p><p class="mt-3 text-xs text-gray-500"><?= e($review['name']) ?> · <?= e(date('M Y',strtotime($review['created_at']))) ?></p></article><?php endforeach; ?></div><?php else: ?><p class="mt-4 flex items-center gap-3 rounded-2xl bg-white p-5 text-sm text-gray-600 ring-1 ring-ink/5"><i class="fa-regular fa-comment-dots text-lg text-sage" aria-hidden="true"></i>No reviews yet. Customers can review a fabric after their order is delivered.</p><?php endif; ?>
<?php if($canReview): ?><form data-ajax-form action="<?= e(url('api/reviews.php')) ?>" method="post" class="mt-8 grid max-w-xl gap-3 bg-white p-5"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="product_id" value="<?= (int)$product['id'] ?>"><h3 class="font-serif text-xl">Share your experience</h3><label class="text-sm">Rating<select class="form-control mt-1" name="rating" required><option value="5">5 — Loved it</option><option value="4">4 — Very good</option><option value="3">3 — Good</option><option value="2">2 — Not for me</option><option value="1">1 — Disappointed</option></select></label><label class="text-sm">Title (optional)<input class="form-control mt-1" name="title" maxlength="150"></label><label class="text-sm">Your review<textarea class="form-control mt-1" name="review" minlength="10" maxlength="2000" rows="4" required></textarea></label><button class="w-fit rounded-full bg-forest px-5 py-2 text-sm text-white">Submit for review</button></form><?php elseif(current_user()&&current_user()['role']==='customer'): ?><p class="mt-6 text-xs text-gray-500">Verified product reviews are available after a delivered order.</p><?php endif; ?></section>
<?php if ($related): ?><section class="py-16"><h2 class="font-serif text-3xl">You might also like</h2><div class="mt-7 grid grid-cols-2 gap-3 sm:gap-5 lg:grid-cols-4"><?php foreach($related as $product): require __DIR__ . '/includes/product-card.php'; endforeach; ?></div></section><?php endif; ?>
